using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[Route("api")]
public class ResultsController(RaceDayContext db) : ApiControllerBase
{
 public record ResultDto(int EnrolmentId,int FinishingPosition,string FinishTime);
 public record UpdateResultDto(int FinishingPosition,string FinishTime);
 [HttpPost("events/{eventId:int}/results")] public async Task<IActionResult> Create(int eventId,ResultDto d){if(RequireRole("Organiser") is IActionResult e)return e;if(!await db.Events.AnyAsync(x=>x.EventID==eventId))return NotFound("Event not found.");if(!await db.EventOrganisers.AnyAsync(x=>x.EventID==eventId&&x.UserID==CurrentUserId))return Forbid();var r=await db.Registrations.SingleOrDefaultAsync(x=>x.RegistrationID==d.EnrolmentId&&x.EventID==eventId);if(r is null)return NotFound("Enrolment not found for event.");if(!TimeSpan.TryParse(d.FinishTime,out var t)||d.FinishingPosition<1)return BadRequest("Use a valid finish time such as 01:12:35 and a positive position.");if(await db.Results.AnyAsync(x=>x.RegistrationID==r.RegistrationID))return Conflict("Result already exists; use PUT to update it.");var result=new Result{RegistrationID=r.RegistrationID,ChipTime=t,FinishTime=DateTime.Today.Add(t),PositionOverall=d.FinishingPosition,PositionCategory=d.FinishingPosition};db.Results.Add(result);await db.SaveChangesAsync();return StatusCode(201,result);}
 [HttpPut("events/{eventId:int}/results/{resultId:int}")] public async Task<IActionResult> Update(int eventId,int resultId,UpdateResultDto d){if(RequireRole("Organiser") is IActionResult e)return e;if(!await db.EventOrganisers.AnyAsync(x=>x.EventID==eventId&&x.UserID==CurrentUserId))return Forbid();var result=await (from rs in db.Results join r in db.Registrations on rs.RegistrationID equals r.RegistrationID where rs.ResultID==resultId&&r.EventID==eventId select rs).SingleOrDefaultAsync();if(result is null)return NotFound();if(!TimeSpan.TryParse(d.FinishTime,out var t)||d.FinishingPosition<1)return BadRequest("Invalid time or position.");result.ChipTime=t;result.FinishTime=DateTime.Today.Add(t);result.PositionOverall=d.FinishingPosition;result.PositionCategory=d.FinishingPosition;await db.SaveChangesAsync();return Ok(result);}
 [HttpGet("results/me")] public async Task<IActionResult> Mine(){if(RequireRole("Participant") is IActionResult e)return e;var rows=await (from rs in db.Results join r in db.Registrations on rs.RegistrationID equals r.RegistrationID join ev in db.Events on r.EventID equals ev.EventID where r.UserID==CurrentUserId select new{rs.ResultID,Event=ev.EventName,rs.FinishTime,rs.ChipTime,FinishingPosition=rs.PositionOverall,rs.PositionCategory,rs.Pace}).ToListAsync();return Ok(rows);}
 [HttpGet("events/{eventId:int}/results")] public async Task<IActionResult> ForEvent(int eventId){if(RequireRole("Organiser") is IActionResult e)return e;if(!await db.Events.AnyAsync(x=>x.EventID==eventId))return NotFound();if(!await db.EventOrganisers.AnyAsync(x=>x.EventID==eventId&&x.UserID==CurrentUserId))return Forbid();var rows=await (from rs in db.Results join r in db.Registrations on rs.RegistrationID equals r.RegistrationID join u in db.Users on r.UserID equals u.UserID where r.EventID==eventId select new{rs.ResultID,r.RegistrationID,Participant=u.FirstName+" "+u.LastName,rs.FinishTime,rs.ChipTime,FinishingPosition=rs.PositionOverall,rs.PositionCategory}).ToListAsync();return Ok(rows);}
}
